/// 按名字取编译期生成的档案表；名字不在表里时返回 `None`。
pub fn embedded(name: &str) -> Option<&'static Table> {
    tables()
        .iter()
        .find(|(entry, _)| *entry == name)
        .map(|(_, table)| table)
}

static NAMES: [&str; 6] = [
    "ascend",
    "cpu",
    "intel",
    "metal",
    "musa",
    "nvidia",
];

/// 生成表里的档案名，按文件名升序。
pub fn names() -> &'static [&'static str] {
    &NAMES
}
